mapper.select:
SELECT id, ai_decision_id, account_no, broker_type, stock_code,
       order_side, order_type, order_price, order_quantity, order_amount,
       order_status, idempotency_key, request_reason, broker_order_no,
       requested_at, updated_at
FROM order_request
WHERE account_no = #{accountNo}

  AND broker_type = #{mode}

ORDER BY requested_at DESC
LIMIT #{limit}
